test("sekret webhooka jest fail-closed i wymaga zgodnej wartości",()=>{expect(checkSecret(null,undefined)).toBe("unconfigured");expect(checkSecret("","")).toBe("unconfigured");expect(checkSecret(null,"x".repeat(64))).toBe("unauthorized");expect(checkSecret("z".repeat(64),"x".repeat(64))).toBe("unauthorized");expect(checkSecret("x".repeat(64),"x".repeat(64))).toBe("ok");});
